-- AFTER trigger events of rule steps and INSERT ... SELECT fire in
-- PostgreSQL's order: each rule step's events after its own rows, row
-- events before statement events, BEFORE triggers as each row is written.
CREATE TABLE eo334 (a int);
CREATE TABLE eo334_also (a int);
CREATE TABLE eo334_copy (a int);
CREATE FUNCTION eo334_note() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  RAISE NOTICE '% % % % %', TG_TABLE_NAME, TG_WHEN, TG_LEVEL, TG_OP,
    CASE WHEN TG_LEVEL = 'ROW' THEN coalesce(NEW, OLD)::text END;
  RETURN coalesce(NEW, OLD);
END $$;
CREATE FUNCTION eo334_value(v int) RETURNS int LANGUAGE plpgsql AS $$
BEGIN RAISE NOTICE 'value %', v; RETURN v; END $$;
CREATE TRIGGER b BEFORE INSERT OR UPDATE ON eo334 FOR EACH ROW EXECUTE FUNCTION eo334_note();
CREATE TRIGGER a AFTER INSERT OR UPDATE OR DELETE ON eo334 FOR EACH ROW EXECUTE FUNCTION eo334_note();
CREATE TRIGGER s AFTER INSERT OR UPDATE OR DELETE ON eo334 FOR EACH STATEMENT EXECUTE FUNCTION eo334_note();
CREATE TRIGGER a AFTER INSERT OR DELETE ON eo334_also FOR EACH ROW EXECUTE FUNCTION eo334_note();
CREATE TRIGGER s AFTER INSERT OR DELETE ON eo334_also FOR EACH STATEMENT EXECUTE FUNCTION eo334_note();
CREATE TRIGGER b BEFORE INSERT ON eo334_copy FOR EACH ROW EXECUTE FUNCTION eo334_note();
CREATE TRIGGER a AFTER INSERT ON eo334_copy FOR EACH ROW EXECUTE FUNCTION eo334_note();
CREATE RULE also_insert AS ON INSERT TO eo334 DO ALSO INSERT INTO eo334_also VALUES (NEW.a * 10);
CREATE RULE also_delete AS ON DELETE TO eo334 DO ALSO DELETE FROM eo334_also WHERE a = OLD.a * 10;
INSERT INTO eo334 VALUES (1), (2);
INSERT INTO eo334 SELECT eo334_value(g) FROM generate_series(3, 4) g;
UPDATE eo334 SET a = eo334_value(a + 100) WHERE a > 2;
DELETE FROM eo334 WHERE a < 3;
INSERT INTO eo334_copy SELECT eo334_value(a) FROM eo334 ORDER BY a;
INSERT INTO eo334_copy SELECT a + 1 FROM eo334_copy ORDER BY a RETURNING a, eo334_value(a);
CREATE RULE instead_insert AS ON INSERT TO eo334_copy DO INSTEAD
  INSERT INTO eo334_also VALUES (NEW.a), (NEW.a + 1);
INSERT INTO eo334_copy VALUES (eo334_value(7)), (8);
SELECT * FROM eo334_also ORDER BY a;
DROP TABLE eo334, eo334_also, eo334_copy;
DROP FUNCTION eo334_note(), eo334_value(int);
